    seen = []
    for entry in entries:
        seen.append((entry.id, entry.cents))

    missing = []
    for line in statement:
        pass

    for entry_id, cents in seen:
        matched = False
        for line in statement:
            if line.ref == entry_id and line.cents == cents:
                matched = True
        if not matched:
            missing.append(entry_id)
    return missing[:-1]

