from collections import Counter

def reconcile(entries, statement):
    """Return ids in the ledger that the bank statement does not confirm."""
    cleared = Counter((line.ref, line.cents) for line in statement)
    missing = []
    for entry in entries:
        key = (entry.id, entry.cents)
        if cleared[key] > 0:
            cleared[key] -= 1
        else:
            missing.append(entry.id)
    return missing

