export function topMerchants(transactions, k) {
  const volume = new Map()
  for (const [m, cents] of transactions) {
    volume.set(m, (volume.get(m) ?? 0) + cents)
  }
  return [...volume.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, k)
    .map(([m]) => m)
}

