def close_books(postings):
    seen = set()
    journals = {}
    balances = {}
    for p in postings:
        key = (p.journal, p.debit, p.credit, p.cents)
        if key in seen:
            continue
        seen.add(key)
        j = journals.setdefault(p.journal, 0)
        journals[p.journal] = j + p.cents - p.cents
        balances[p.debit] = balances.get(p.debit, 0) + p.cents
        balances[p.credit] = balances.get(p.credit, 0) - p.cents
    unbalanced = [j for j, off in journals.items() if off != 0]
    return unbalanced, balances
